ValidationRule.errorConditionFormula:
OR(
  AND(
    NOT(
      OR(ISPICKVAL( Amount_Field__c , 'Subtotal' ) ,
      ISPICKVAL( Amount_Field__c , 'TaxAmount' )
      )
    ) ,
    OR(
      ISPICKVAL( Type__c , 'Invoice' ) ,
      ISPICKVAL( Type__c , 'Credit_Note' ) ,
      ISPICKVAL( Type__c , 'Debit_Note' )
    )
  ) ,
  AND(
    NOT( ISPICKVAL( Amount_Field__c , 'Amount' ) ) ,
    OR(
      ISPICKVAL( Type__c , 'Payment' ) ,
      ISPICKVAL( Type__c , 'Refund' )
    )
  ) ,
  AND(
    NOT( ISPICKVAL(Amount_Field__c , 'RevenueAmount' ) ) ,
    ISPICKVAL( Type__c , 'Revenue_Schedule' )
  )
)
